function parseJsonAutoFix(raw) {
  if (!raw) throw new Error("Input vacío");

  let txt = raw.toString().trim();

  // 1️⃣ Quitar fences ```json ``` o ```
  txt = txt
    .replace(/^```(?:json)?/i, '')
    .replace(/```$/i, '')
    .trim();

  // 2️⃣ Intento directo
  try {
    return JSON.parse(txt);
  } catch (_) {}

  // 3️⃣ Reparar comillas simples → dobles
  try {
    return JSON.parse(
      txt
        .replace(/'/g, '"')
        .replace(/,\s*}/g, '}')
        .replace(/,\s*]/g, ']')
    );
  } catch (_) {}

  // 4️⃣ Reparar JSON escapado (doble stringify)
  try {
    return JSON.parse(JSON.parse(`"${txt.replace(/"/g, '\\"')}"`));
  } catch (_) {}

  // 5️⃣ Último intento: eval seguro
  try {
    // ⚠️ Solo usar si confías en el origen
    return Function('"use strict"; return (' + txt + ')')();
  } catch (e) {
    throw new Error("No se pudo parsear JSON:\n" + txt);
  }
}

return {
  output: parseJsonAutoFix($input.first().json.text)
};

